def transform(grid):
    from collections import Counter
    if not grid or not grid[0]:
        return grid

    counts = Counter()
    for row in grid:
        for cell in row:
            counts[cell] += 1

    bg = max(counts, key=counts.get)
    candidates = sorted([c for c in counts if c != bg], key=lambda c: counts[c], reverse=True)

    frame_color = candidates[0]
    content = candidates[1] if len(candidates) > 1 else frame_color

    # Check all non-bg colors for valid frames
    candidates_frames = []
    for color in counts:
        if color == bg:
            continue

        positions = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]
        if not positions:
            continue

        min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
        min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

        # Check rectangular border integrity
        valid = True
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                on_border = (r == min_r or r == max_r or c == min_c or c == max_c)
                if on_border and grid[r][c] != color:
                    valid = False
                    break
            if not valid:
                break

        if not valid:
            continue

        # Check if frame has the 'content' color inside
        has_content = False
        for r in range(min_r + 1, max_r):
            for c in range(min_c + 1, max_c):
                if grid[r][c] == content:
                    has_content = True
                    break
            if has_content:
                break

        candidates_frames.append({
            'color': color, 
            'min_r': min_r, 
            'max_r': max_r,
            'min_c': min_c, 
            'max_c': max_c,
            'area': (max_r - min_r + 1) * (max_c - min_c + 1),
            'has_content': has_content
        })

    # Select best frame: Largest area with content present
    frames_with_content = [f for f in candidates_frames if f['has_content']]
    if frames_with_content:
        best = max(frames_with_content, key=lambda f: f['area'])
    else:
        best = max(candidates_frames, key=lambda f: f['area'])

    if best:
        color = best['color']
        br, er, bc, ec = best['min_r'], best['max_r'], best['min_c'], best['max_c']
        h, w = er - br + 1, ec - bc + 1

        output_grid = []
        for r in range(h):
            row = []
            for c in range(w):
                val = grid[br + r][bc + c]
                # Mapping: Frame Color -> Content Color
                # Background and other colors -> themselves
                if val == color:
                    row.append(content)
                else:
                    row.append(val)
            output_grid.append(row)
        return output_grid

    return grid
